37:     /** 可选条件：先取中台产品能力，再按渠道规则收窄（金额上限、期限、开放开关）。 */
38:     @SuppressWarnings("unchecked")
39:     public Map<String, Object> options(String channelId, String creditId) {
40:         Map<String, Object> middleOptions = middle.drawdownOptions(creditId);
41:         List<Map<String, Object>> products = ((List<Object>) middleOptions.get("products")).stream()
42:                 .map(item -> (Map<String, Object>) item)
43:                 .map(p -> narrowByChannel(channelId, p))
44:                 .filter(p -> p != null)
45:                 .toList();
46:         return Map.of("channelId", channelId, "creditId", creditId, "products", products);
47:     }
