49:     @SuppressWarnings("unchecked")
50:     private Map<String, Object> narrowByChannel(String channelId, Map<String, Object> product) {
51:         return ruleRepo.findByChannelId(channelId).stream()
52:                 .filter(rule -> rule.isEnabled() && rule.getProductId().equals(product.get("productId")))
53:                 .findFirst()
54:                 .map(rule -> {
55:                     BigDecimal capped = ((BigDecimal) product.get("maxAmount")).min(rule.getMaxAmount());
56:                     List<Integer> terms = ((List<Integer>) product.get("terms")).stream()
57:                             .filter(t -> rule.termList().contains(t))
58:                             .toList();
59:                     if (terms.isEmpty() || capped.compareTo((BigDecimal) product.get("minAmount")) < 0) {
60:                         return null; // 渠道开放范围收窄到不可用时直接不透出
61:                     }
62:                     return Map.<String, Object>of(
63:                             "productId", product.get("productId"),
64:                             "productName", product.get("productName"),
65:                             "minAmount", product.get("minAmount"),
66:                             "maxAmount", capped,
67:                             "terms", terms,
68:                             "repaymentModes", product.get("repaymentModes"),
69:                             "availableAmount", product.get("availableAmount"),
70:                             "channelMaxAmount", rule.getMaxAmount());
71:                 })
72:                 .orElse(null);
73:     }
