75:     /** 提款申请入口：渠道校验自己的开放规则（金额、期限），转换字段后调用中台。 */
76:     @SuppressWarnings("unchecked")
77:     public Map<String, Object> applyDrawdown(String channelId, Map<String, Object> request) {
78:         String creditId = String.valueOf(request.get("creditId"));
79:         String productId = String.valueOf(request.get("productId"));
80:         BigDecimal amount = new BigDecimal(String.valueOf(request.get("amount")));
81:         int termMonths = Integer.parseInt(String.valueOf(request.get("termMonths")));
82: 
83:         ChannelProductRule rule = ruleRepo.findByChannelId(channelId).stream()
84:                 .filter(r -> r.getProductId().equals(productId) && r.isEnabled())
85:                 .findFirst()
86:                 .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "PRODUCT_NOT_OPEN"));
87:         if (amount.compareTo(rule.getMaxAmount()) > 0) {
88:             throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_AMOUNT_LIMIT");
89:         }
90:         if (!rule.termList().contains(termMonths)) {
91:             throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_TERM_LIMIT");
92:         }
93: 
94:         // 字段转换：渠道语义 → 中台契约（quote → apply 两步，均按 docs/接口契约-阶段2.md）
95:         Map<String, Object> quote = middle.quote(Map.of(
96:                 "creditId", creditId,
97:                 "productId", productId,
98:                 "amount", amount,
99:                 "termMonths", termMonths,
100:                 "repaymentMode", String.valueOf(request.get("repaymentMode")),
101:                 "firstRepaymentDate", String.valueOf(request.getOrDefault("firstRepaymentDate", ""))));
102:         Map<String, Object> applied = middle.applyDrawdown(String.valueOf(quote.get("quoteNo")),
103:                 String.valueOf(request.get("payeeName")),
104:                 String.valueOf(request.get("payeeAccount")),
105:                 String.valueOf(request.getOrDefault("purpose", "")));
106: 
107:         String channelRefNo = nextRef();
108:         saveRecord(channelRefNo, channelId, BizType.DRAWDOWN, String.valueOf(applied.get("bizOrderNo")),
109:                 displayOf(String.valueOf(applied.get("status"))));
110:         return Map.of("channelRefNo", channelRefNo, "displayStatus", "PROCESSING");
111:     }
