185:     /**
186:      * 付款结果落业务单。幂等：业务单已终态、或该结果已生效时，直接确认不产生任何新记录。
187:      */
188:     @Transactional
189:     public void onPaymentResult(DrawdownOrder order, String result) {
190:         if (order.terminal()) {
191:             return; // 幂等：终态后收到的任何结果只影响外部流水，不改业务单
192:         }
193:         order.setUpdatedAt(Ids.now());
194:         if ("SUCCESS".equals(result)) {
195:             if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.SUCCESS) {
196:                 return; // 幂等：成功已受理过
197:             }
198:             order.setPaymentStatus(DrawdownOrder.PaymentStatus.SUCCESS);
199:             order.setStatus(DrawdownOrder.Status.EXTERNAL_SUCCESS_BOOKING_PENDING);
200:             order.setBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK);
201:             book(order); // 同步尝试入账；失败转 RETRY_NEEDED 由补偿任务继续
202:         } else {
203:             if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.FAILED) {
204:                 return;
205:             }
206:             order.setPaymentStatus(DrawdownOrder.PaymentStatus.FAILED);
207:             order.setStatus(DrawdownOrder.Status.FAILED);
208:             limitService.releasePreOccupied(order.getCreditId(), order.getBizOrderNo(), order.getProductId(),
209:                     requiresGuarantee(order.getProductId()), order.getAmount());
210:         }
211:     }
